export function packedWeight(caseWeight,bikeWeight,packingWeight,limit){const values=[caseWeight,bikeWeight,packingWeight,limit].map(Number);if(values.some(x=>!Number.isFinite(x)||x<0)||values[3]<=0)throw new Error('Enter valid weights and a positive allowance.');const total=Number((values[0]+values[1]+values[2]).toFixed(2));return {total,remaining:Number((values[3]-total).toFixed(2)),over:total>values[3]};}

